window.MASS_ORDINARY = [
  { title: "進堂禮", la: "Ritus initiales", en: "Introductory Rites", parts: [
    { zh: "因父、及子、及聖神之名。阿們。", la: "In nomine Patris, et Filii, et Spiritus Sancti. Amen.", en: "In the name of the Father, and of the Son, and of the Holy Spirit. Amen." },
    { zh: "願主與你們同在。", la: "Dominus vobiscum.", en: "The Lord be with you." },
    { zh: "也與你的心靈同在。", la: "Et cum spiritu tuo.", en: "And with your spirit." },
    { zh: "上主，求你垂憐。基督，求你垂憐。上主，求你垂憐。", la: "Kyrie, eleison. Christe, eleison. Kyrie, eleison.", en: "Lord, have mercy. Christ, have mercy. Lord, have mercy." },
    { zh: "願光榮歸於天主於高天，主愛的人才享平安。", la: "Gloria in excelsis Deo, et in terra pax hominibus bonae voluntatis.", en: "Glory to God in the highest, and on earth peace to people of good will." },
    { zh: "集禱經：上主，求你俯聽我們的祈禱。因你的聖子、我們的主耶穌基督，他和你及聖神，是唯一天主，永生永王。阿們。", la: "Oremus. Per Christum Dominum nostrum. Amen.", en: "Let us pray. Through Christ our Lord. Amen." }
  ]},
  { title: "聖道禮", la: "Liturgia Verbi", en: "Liturgy of the Word", parts: [
    { zh: "讀經一", la: "Lectio prima", en: "First Reading" },
    { zh: "上主的話。——感謝天主。", la: "Verbum Domini. — Deo gratias.", en: "The word of the Lord. — Thanks be to God." },
    { zh: "答唱詠", la: "Psalmus responsorius", en: "Responsorial Psalm" },
    { zh: "讀經二", la: "Lectio secunda", en: "Second Reading" },
    { zh: "上主的話。——感謝天主。", la: "Verbum Domini. — Deo gratias.", en: "The word of the Lord. — Thanks be to God." },
    { zh: "福音前歡呼：亞肋路亞。", la: "Alleluia, alleluia.", en: "Alleluia, alleluia." },
    { zh: "願主與你們同在。——也與你的心靈同在。恭讀聖╳╳福音。——主，願光榮歸於你。", la: "Dominus vobiscum. — Et cum spiritu tuo. Lectio sancti Evangelii secundum N. — Gloria tibi, Domine.", en: "The Lord be with you. — And with your spirit. A reading from the holy Gospel according to N. — Glory to you, O Lord." },
    { zh: "上主的福音。——基督，我們讚美你。", la: "Verbum Domini. — Laus tibi, Christe.", en: "The Gospel of the Lord. — Praise to you, Lord Jesus Christ." },
    { zh: "講道", la: "Homilia", en: "Homily" },
    { zh: "信經：我信唯一的天主，全能的天父，天地萬物，無論有形無形，都是祂所創造的。我信唯一的主、耶穌基督、天主的獨生子。祂在萬世之前，由父所生。祂是出於天主的天主，出於光明的光明，出於真天主的真天主。祂是聖父所生，而非聖父所造，與聖父同性同體，萬物是藉著祂而造成的。祂為了我們人類，並為了我們的得救，從天降下。祂因聖神降孕，由童貞瑪利亞取得肉軀，而成為人。祂在般雀比拉多執政時，為我們被釘在十字架上，受難而被埋葬。祂正如聖經所載，第三日復活了。祂升了天，坐在聖父的右邊。祂還要光榮地降來，審判生者死者，祂的神國萬世無疆。我信聖神，祂是主及賦予生命者，由聖父及聖子所共發。祂和聖父及聖子，同受欽崇，同享光榮，祂曾藉先知們發言。我信唯一、至聖、至公、從宗徒傳下來的教會。我承認赦罪的聖洗，只有一個。我期待死人的復活，及來世的生命。阿們。", la: "Credo in unum Deum, Patrem omnipotentem, factorem caeli et terrae, visibilium omnium et invisibilium.", en: "I believe in one God, the Father almighty, maker of heaven and earth, of all things visible and invisible. I believe in one Lord Jesus Christ, the Only Begotten Son of God. I believe in the Holy Spirit, the Lord, the giver of life. I believe in one, holy, catholic and apostolic Church. I look forward to the resurrection of the dead and the life of the world to come. Amen." },
    { zh: "信友禱詞", la: "Oratio universalis", en: "Universal Prayer" }
  ]},
  { title: "聖祭禮", la: "Liturgia Eucharistica", en: "Liturgy of the Eucharist", parts: [
    { zh: "願主從你的手中，收納這份祭品，為讚美和光榮祂的聖名，也為我們和祂整個聖教會的益處。", la: "Suscipiat Dominus sacrificium de manibus tuis ad laudem et gloriam nominis sui, ad utilitatem quoque nostram totiusque Ecclesiae suae sanctae.", en: "May the Lord accept the sacrifice at your hands for the praise and glory of his name, for our good and the good of all his holy Church." },
    { zh: "上主，求你接納我們和整個教會的奉獻。因主耶穌基督之名。阿們。", la: "Per Christum Dominum nostrum. Amen.", en: "Through Christ our Lord. Amen." },
    { zh: "願主與你們同在。——也與你的心靈同在。請舉心向上。——我們全心歸向上主。請大家感謝主、我們的天主。——這是理所當然的。", la: "Dominus vobiscum. Et cum spiritu tuo. Sursum corda. Habemus ad Dominum. Gratias agamus Domino Deo nostro. Dignum et iustum est.", en: "The Lord be with you. And with your spirit. Lift up your hearts. We lift them up to the Lord. Let us give thanks to the Lord our God. It is right and just." },
    { zh: "聖、聖、聖，上主、萬有的天主。你的光榮充滿天地。歡呼之聲，響徹雲霄。奉上主名而來的，當受讚美。歡呼之聲，響徹雲霄。", la: "Sanctus, Sanctus, Sanctus Dominus Deus Sabaoth. Pleni sunt caeli et terra gloria tua. Hosanna in excelsis. Benedictus qui venit in nomine Domini. Hosanna in excelsis.", en: "Holy, Holy, Holy Lord God of hosts. Heaven and earth are full of your glory. Hosanna in the highest. Blessed is he who comes in the name of the Lord. Hosanna in the highest." },
    { zh: "你們大家拿去吃：這就是我的身體，將為你們而犧牲。", la: "Accipite et manducate ex hoc omnes: hoc est enim Corpus meum, quod pro vobis tradetur.", en: "Take this, all of you, and eat of it: for this is my Body, which will be given up for you." },
    { zh: "你們大家拿去喝：這一杯就是我的血，新而永久的盟約之血，將為你們和眾人傾流，以赦免罪過。你們要這樣做，來紀念我。", la: "Accipite et bibite ex eo omnes: hic est enim calix Sanguinis mei, novi et aeterni testamenti, qui pro vobis et pro multis effundetur in remissionem peccatorum. Hoc facite in meam commemorationem.", en: "Take this, all of you, and drink from it: for this is the chalice of my Blood, the Blood of the new and eternal covenant, which will be poured out for you and for many for the forgiveness of sins. Do this in memory of me." },
    { zh: "信德的奧蹟。——主啊！我們傳報你的死亡，歌頌你的復活，期待你光榮地來臨。", la: "Mysterium fidei. Mortem tuam annuntiamus, Domine, et tuam resurrectionem confitemur, donec venias.", en: "The mystery of faith. We proclaim your Death, O Lord, and profess your Resurrection until you come again." },
    { zh: "藉著基督、偕同基督、在基督內，願光榮歸於你，全能的天主聖父，及與你同體的聖神，世世無窮。——阿們。", la: "Per ipsum, et cum ipso, et in ipso, est tibi Deo Patri omnipotenti, in unitate Spiritus Sancti, omnis honor et gloria per omnia saecula saeculorum. Amen.", en: "Through him, and with him, and in him, O God, almighty Father, in the unity of the Holy Spirit, all glory and honor is yours, for ever and ever. Amen." }
  ]},
  { title: "領主禮", la: "Ritus Communionis", en: "Communion Rite", parts: [
    { zh: "我們的天父，願你的名受顯揚，願你的國來臨，願你的旨意奉行在人間，如同在天上。求你今天賞給我們日用的食糧，求你寬恕我們的罪過，如同我們寬恕別人一樣。不要讓我們陷於誘惑，但救我們免於凶惡。", la: "Pater noster, qui es in caelis: sanctificetur nomen tuum; adveniat regnum tuum; fiat voluntas tua, sicut in caelo et in terra. Panem nostrum cotidianum da nobis hodie; et dimitte nobis debita nostra, sicut et nos dimittimus debitoribus nostris; et ne nos inducas in tentationem; sed libera nos a malo.", en: "Our Father, who art in heaven, hallowed be thy name; thy kingdom come; thy will be done on earth as it is in heaven. Give us this day our daily bread; and forgive us our trespasses, as we forgive those who trespass against us; and lead us not into temptation, but deliver us from evil." },
    { zh: "上主，我不堪當你到我心裡來，只要你說一句話，我的靈魂就會痊癒。", la: "Domine, non sum dignus, ut intres sub tectum meum, sed tantum dic verbo, et sanabitur anima mea.", en: "Lord, I am not worthy that you should enter under my roof, but only say the word and my soul shall be healed." },
    { zh: "領主詠：基督的聖體。——阿們。", la: "Corpus Christi. — Amen.", en: "The Body of Christ. — Amen." },
    { zh: "領聖體後經：上主，求你俯聽我們的祈禱。因主耶穌基督之名。阿們。", la: "Per Christum Dominum nostrum. Amen.", en: "Let us pray. Through Christ our Lord. Amen." }
  ]},
  { title: "禮成式", la: "Ritus conclusionis", en: "Concluding Rites", parts: [
    { zh: "願主與你們同在。——也與你的心靈同在。", la: "Dominus vobiscum. — Et cum spiritu tuo.", en: "The Lord be with you. — And with your spirit." },
    { zh: "願全能的天主，父、及子、及聖神，降福你們。——阿們。", la: "Benedicat vos omnipotens Deus, Pater, et Filius, et Spiritus Sanctus. — Amen.", en: "May almighty God bless you, the Father, and the Son, and the Holy Spirit. — Amen." },
    { zh: "彌撒禮成。——感謝天主。", la: "Ite, missa est. — Deo gratias.", en: "Go forth, the Mass is ended. — Thanks be to God." }
  ]}
];
